<?php require '_layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$id=(int)($d['id']??0);$role=in_array($d['role'],['owner','manager','staff'])?$d['role']:'staff';$email=strtolower(trim((string)($d['email']??'')));$msg='ok=1';
 if(isset($d['del'])&&$id){$u=$db->prepare('SELECT username FROM admin_users WHERE id=?');$u->execute([$id]);if($u->fetchColumn()!==$_SESSION['u'])$db->prepare('DELETE FROM admin_users WHERE id=?')->execute([$id]);else $msg='err=You cannot delete yourself';}
 elseif($id){$act=isset($d['active'])?1:0;$u=$db->prepare('SELECT username FROM admin_users WHERE id=?');$u->execute([$id]);if($u->fetchColumn()===$_SESSION['u']){$act=1;$role='owner';}
  if(!filter_var($email,FILTER_VALIDATE_EMAIL))$msg='err=Enter a valid recovery email address';else try{$db->prepare('UPDATE admin_users SET role=?,active=?,email=? WHERE id=?')->execute([$role,$act,$email,$id]);if(strlen($d['password'])>=12)$db->prepare('UPDATE admin_users SET pass_hash=?,must_change=1 WHERE id=?')->execute([password_hash($d['password'],PASSWORD_DEFAULT),$id]);elseif($d['password']!=='')$msg='err=Password must be 12+ characters';}catch(Throwable $x){$msg='err=That username or recovery email is already in use';}}
 else{$un=preg_replace('/[^a-z0-9_.-]/','',strtolower(trim($d['username'])));if($un===''||strlen($d['password'])<12||!filter_var($email,FILTER_VALIDATE_EMAIL))$msg='err=Enter a username, valid recovery email and password of 12+ characters';else try{$db->prepare('INSERT INTO admin_users(username,email,pass_hash,role) VALUES(?,?,?,?)')->execute([$un,$email,password_hash($d['password'],PASSWORD_DEFAULT),$role]);}catch(Exception $x){$msg='err=That username or recovery email already exists';}}
 header('Location: users.php?'.$msg);exit;}
ahead('Staff logins','users.php');?><?=isset($_GET['ok'])?'<p class="okm">Saved</p>':''?><?=isset($_GET['err'])?'<p class="bad">'.e($_GET['err']).'</p>':''?>
